15	)
16	
17	// JSON wire types — kept local to the CLI because they translate model
18	// internals (raw State, line numbers) into agent-friendly shapes.
19	
20	type jsonBlock struct {
21		ID             string   `json:"id"`
22		State          string   `json:"state"`
23		Title          string   `json:"title"`
24		Type           string   `json:"type"`
25		Parent         string   `json:"parent"`
26		Repo           string   `json:"repo"`
27		Tags           []string `json:"tags"`
28		Started        string   `json:"started"`
29		PR             string   `json:"pr"`
30		WaitingSince   string   `json:"waitingSince,omitempty"`
31		WaitingDays    int      `json:"waitingDays,omitempty"`
32		Files          []string `json:"files"`
33		Acceptance     string   `json:"acceptance"`
34		NotesRef       string   `json:"notesRef"`
35		Status         string   `json:"status"`
36		ActiveChildren []string `json:"activeChildren"`
37	}
38	
39	type jsonSection struct {
40		Name   string      `json:"name"`
41		Count  int         `json:"count"`
42		Cap    int         `json:"cap"`
43		Blocks []jsonBlock `json:"blocks"`
44	}
45	
46	type jsonStatus struct {
47		Dir      string        `json:"dir"`
48		Sections []jsonSection `json:"sections"`
49	}
50	
51	func newStatusCmd() *cobra.Command {
52		var asJSON bool
53	
54		cmd := &cobra.Command{
55			Use:   "status",
56			Args:  cobra.NoArgs,
57			Short: "Print Now/Next/Someday in a styled, scriptable summary",
58			Long: `status prints a snapshot of the worklog's front page.
59	
60	By default the output is Lip Gloss-styled text for humans. With --json
61	the same data is emitted as a structured JSON document (including the
62	error path) so agents can parse a single value regardless of outcome.`,
63			RunE: func(cmd *cobra.Command, args []string) error {
64				return runStatus(cmd, asJSON)
65			},
66		}
67		cmd.Flags().BoolVar(&asJSON, "json", false, "emit a JSON document instead of styled text")
68		return cmd
69	}
70	
71	func runStatus(cmd *cobra.Command, asJSON bool) error {
72		wd, err := resolveWorkdir()
73		if err != nil {
74			return jsonOrTextError(cmd, asJSON, 1, "%v", err)
75		}
76	
77		doc, err := parse.File(wd.WorkMD())
78		if err != nil {
79			if errors.Is(err, model.ErrWorkMDMissing) {
80				return jsonOrTextError(cmd, asJSON, 1, "WORK.md not found at %s", wd.WorkMD())
81			}
82			return jsonOrTextError(cmd, asJSON, 1, "%v", err)
83		}
84	
85		if asJSON {
86			return emitStatusJSON(cmd, wd.Root, doc)
87		}
88		return emitStatusText(cmd, doc)
89	}
