91	func emitStatusJSON(cmd *cobra.Command, dir string, doc *model.WorkDoc) error {
92		payload := jsonStatus{
93			Dir: dir,
94			Sections: []jsonSection{
95				buildJSONSection(doc, model.SectionNow, validate.NowCap),
96				buildJSONSection(doc, model.SectionWaiting, 0),
97				buildJSONSection(doc, model.SectionNext, 0),
98				buildJSONSection(doc, model.SectionSomeday, 0),
99			},
100		}
101		return emitJSON(cmd.OutOrStdout(), payload)
102	}
103	
104	func buildJSONSection(doc *model.WorkDoc, name model.SectionName, cap int) jsonSection {
105		out := jsonSection{
106			Name:   string(name),
107			Cap:    cap,
108			Blocks: []jsonBlock{},
109		}
110		sec := doc.Section(name)
111		if sec == nil {
112			return out
113		}
114		out.Count = len(sec.Blocks)
115		for _, b := range sec.Blocks {
116			out.Blocks = append(out.Blocks, toJSONBlock(b))
117		}
118		return out
