121	func toJSONBlock(b model.Block) jsonBlock {
122		return jsonBlock{
123			ID:             b.ID,
124			State:          b.State.Label(),
125			Title:          b.Title,
126			Type:           string(b.Type),
127			Parent:         b.Parent,
128			Repo:           b.Repo,
129			Tags:           defaultStringSlice(b.Tags),
130			Started:        b.Started,
131			PR:             b.PR,
132			WaitingSince:   b.WaitingSince,
133			WaitingDays:    waitingAge(b.WaitingSince, time.Now()),
134			Files:          defaultStringSlice(b.Files),
135			Acceptance:     b.Acceptance,
136			NotesRef:       b.NotesRef,
137			Status:         b.Status,
138			ActiveChildren: defaultStringSlice(b.ActiveChildren),
139		}
140	}
141	
142	func waitingAge(since string, now time.Time) int {
143		if since == "" {
144			return 0
145		}
146		t, err := time.Parse("2006-01-02", since)
147		if err != nil {
148			return 0
149		}
150		days := int(now.Truncate(24*time.Hour).Sub(t.Truncate(24*time.Hour)).Hours() / 24)
151		if days < 0 {
152			return 0
153		}
154		return days
155	}
156	
157	// defaultStringSlice replaces a nil slice with an empty one so JSON renders
158	// `[]` instead of `null`. Stable schemas help agents parse with confidence.
159	func defaultStringSlice(in []string) []string {
160		if in == nil {
161			return []string{}
162		}
163		return in
164	}
165	
166	func emitStatusText(cmd *cobra.Command, doc *model.WorkDoc) error {
167		out := cmd.OutOrStdout()
168		now := doc.Section(model.SectionNow)
169		next := doc.Section(model.SectionNext)
170		someday := doc.Section(model.SectionSomeday)
171	
172		// ## Now header with cap indicator
173		nowCount := 0
174		if now != nil {
175			nowCount = len(now.Blocks)
176		}
177		capStyle := style.CapColor(nowCount, validate.NowCap)
178		fmt.Fprintln(out, style.Heading.Render("## Now ")+
179			capStyle.Render(fmt.Sprintf("(%d of %d)", nowCount, validate.NowCap)))
180		if now != nil {
181			for _, b := range now.Blocks {
182				fmt.Fprintln(out, "  "+renderBlockLine(b))
183			}
184			if len(now.Blocks) == 0 {
185				fmt.Fprintln(out, "  "+style.Dim.Render("<empty>"))
186			}
187		}
188		fmt.Fprintln(out)
189	
190		// ## Waiting — with per-ticket age annotation
191		waiting := doc.Section(model.SectionWaiting)
192		if waiting != nil && len(waiting.Blocks) > 0 {
193			fmt.Fprintln(out, style.Heading.Render("## Waiting"))
194			today := time.Now()
195			maxAge := 0
196			for _, b := range waiting.Blocks {
197				age := waitingAge(b.WaitingSince, today)
198				if age > maxAge {
199					maxAge = age
200				}
201				line := "  " + renderBlockLine(b)
202				if age > 0 {
203					line += " " + style.Dim.Render(fmt.Sprintf("(%d days)", age))
204				}
205				fmt.Fprintln(out, line)
206			}
207			if maxAge > 0 {
208				fmt.Fprintln(out, "  "+style.Warn.Render(fmt.Sprintf("oldest waiting %d days", maxAge)))
209			}
210			fmt.Fprintln(out)
211		}
212	
213		// ## Next — list epics with their Active children, then standalone tickets
214		fmt.Fprintln(out, style.Heading.Render("## Next"))
215		if next == nil || len(next.Blocks) == 0 {
216			fmt.Fprintln(out, "  "+style.Dim.Render("<empty>"))
217		} else {
218			for _, b := range next.Blocks {
219				fmt.Fprintln(out, "  "+renderBlockLine(b))
220				if b.IsEpic() && len(b.ActiveChildren) > 0 {
221					fmt.Fprintln(out, "    "+style.SubHeading.Render("active children: ")+
222						style.Active.Render(strings.Join(b.ActiveChildren, ", ")))
223				}
224			}
225		}
226		fmt.Fprintln(out)
227	
228		// ## Someday — just a count
229		somedayCount := 0
230		if someday != nil {
231			somedayCount = len(someday.Blocks)
232		}
233		fmt.Fprintln(out, style.Heading.Render("## Someday ")+
234			style.Dim.Render(fmt.Sprintf("(%d items)", somedayCount)))
235		return nil
236	}
237	
238	func renderBlockLine(b model.Block) string {
239		var stateBox string
240		switch b.State {
241		case model.StateActive:
242			stateBox = style.Active.Render("[~]")
243		case model.StateDone:
244			stateBox = style.Done.Render("[x]")
245		default:
246			stateBox = style.Pending.Render("[ ]")
247		}
248	
249		var idStyle string
250		if b.IsEpic() {
251			idStyle = style.Epic.Render(strings.ToUpper(b.ID))
252		} else {
253			idStyle = style.SubHeading.Render(strings.ToUpper(b.ID))
254		}
255	
256		parts := []string{stateBox, idStyle}
257		if b.Title != "" {
258			parts = append(parts, b.Title)
259		}
260		if b.Parent != "" {
261			parts = append(parts, style.Dim.Render("(parent: "+b.Parent+")"))
262		}
263		if len(b.Tags) > 0 {
264			var tagStr []string
265			for _, t := range b.Tags {
266				tagStr = append(tagStr, style.Tag.Render(t))
267			}
268			parts = append(parts, strings.Join(tagStr, " "))
269		}
270		return strings.Join(parts, " ")
271	}
